<td>Sangat kuat (dikombinasikan beton)</td>
<td>Tidak untuk struktur beban berat</td>
</tr>
<tr>
<td>Bobot</td>
<td>Lebih berat</td>
<td>Ringan</td>
</tr>
<tr>
<td>Aplikasi umum</td>
<td>Dak lantai</td>
<td>Atap rumah/gudang</td>
</tr>
<tr>
<td>Ketahanan cuaca</td>
<td>Tahan (terlindung beton)</td>
